    @Test
    void simpleAndExtendedConstraintsAreByteIdentical() {
        assertEquals(EXPECTED_SIMPLE_AND_MESSAGE, emitFirstClass("""
                Class f::C
                [
                  c1: $this.n > 1,
                  c2
                  (
                    ~function: $this.n < 10
                    ~message: 'n is ' + $this.n->toString()
                  )
                ]
                {
                  n: Integer[1];
                }
                """));
    }

