    /**
     * The finding that KILLED a planned wall: our grammar already matches engine's real
     * binding — {@code ==} after an operand binds to THAT OPERAND ({@code parseExpression}
     * consumes the trailing equality), so {@code s + 'a' + 'b' == 'x'} is
     * {@code plus([s,'a',equal('b','x')])} on both sides. Byte-pinned here so neither
     * parser drifts from the other unnoticed.
     */
    @Test
    void mixedChainMatchesEngineFlatBinding() {
        assertEquals(EXPECTED_MIXED_CHAIN, emitFirstClass("""
                Class g::C
                [
                  cMinus: $this.n - 1 > 0,
                  cTimes: $this.n * 2 > 0,
                  cDiv: $this.n / 2 > 0,
                  cEq: $this.n == 1,
                  cNeq: $this.n != 1,
                  cAnd: ($this.n > 1) && ($this.n < 9),
                  cOr: ($this.n > 1) || ($this.n < 9),
                  cNot: !($this.n > 1),
                  cChain: $this.s + 'a' + 'b' == 'x',
                  cCall: $this.s->startsWith('a'),
                  cColl: $this.n->in([1, 2, 3])
                ]
                {
                  n: Integer[1];
                  s: String[1];
                }
                """));
    }

    /**
     * Still walled: {@code equal} whose LHS is an explicitly PARENTHESISED arithmetic chain
     * — the only route to an equal-over-arithmetic tree in our grammar. The engine bytes for
     * this form are not yet probed; refuse loudly rather than guess.
     */
    @Test
    void parenthesisedChainComparisonWallsUntilProbed() {
        UnsupportedOperationException e = assertThrows(UnsupportedOperationException.class,
                () -> emitFirstClass("""
                        Class i::C
                        [
                          c: ($this.s + 'a') == 'x'
                        ]
                        {
                          s: String[1];
                        }
                        """));
        assertTrue(e.getMessage().contains("flat-grammar associativity"), e.getMessage());
    }

