    /**
     * Class refs, enum values, lambdas, floats, unary minus, enforcement levels — pinned:
     * {@code .all()} desugars to {@code getAll} spanning DOT..close-paren (a dot-call
     * convention, distinct from arrow-calls' name-only span); an enum value is a plain
     * {@code property} on a {@code packageableElementPtr} (no enumValue node on the wire);
     * an untyped lambda parameter is the bare var (no span, no multiplicity) while a typed
     * one carries genericType + multiplicity + its declaration span; unary minus is a
     * one-parameter func (no collection) spanning the operator token; {@code
     * ~enforcementLevel} sorts FIRST among the constraint's fields.
     */
    @Test
    void ptrEnumLambdaFloatMinusLevelAreByteIdentical() {
        assertEquals(EXPECTED_PTR_ENUM_LAMBDA, emitFirstClass("""
                Class j::C
                [
                  cPtr: j::C.all()->size() > 0,
                  cEnum: $this.st == j::St.UP,
                  cLambda: $this.xs->exists(x|$x > 1),
                  cLambda2: $this.xs->forAll(x: Integer[1]|$x > 1),
                  cFloat: $this.f > 1.5,
                  cNeg: $this.n > -2,
                  cLevel
                  (
                    ~function: $this.n > 3
                    ~enforcementLevel: Warn
                  )
                ]
                {
                  n: Integer[1];
                  f: Float[1];
                  st: j::St[1];
                  xs: Integer[*];
                }
                Enum j::St
                {
                  UP, DOWN
                }
                """));
    }

