    /**
     * Braced lambdas span open-brace..body-end (close brace excluded); a dot-spelled
     * property CALL is a property node with appended arguments spanning the NAME token only
     * (the dot..close-paren span belongs solely to the .all()-family getAll desugar);
     * %2020-01-01 is {@code strictDate} spanning the whole %-literal; qualified properties
     * emit bare bodies with typed-var parameters and no synthesised $this.
     */
    @Test
    void braceAndPropertyCallAndDateAndQualifiedPropertiesAreByteIdentical() {
        assertEquals(EXPECTED_BRACE_PCALL_DATE, emitFirstClass("""
                Class k::C
                [
                  cBrace: $this.xs->map({y | $y + 1})->size() > 0,
                  cPcall: $this.tag('x') == 'y',
                  cDate: $this.d > %2020-01-01
                ]
                {
                  n: Integer[1];
                  d: Date[1];
                  xs: Integer[*];
                  tag(s: String[1]) {$s + $this.n->toString()}: String[1];
                }
                """));
    }

