    /** {@code ~owner} is a SINGLE identifier on the wire ("owner", between name and
     *  sourceInformation); engine rejects a bracketed owner list outright. */
    @Test
    void constraintOwnerIsByteIdentical() {
        assertEquals(EXPECTED_OWNER, emitFirstClass("""
                Class k2::C
                [
                  cOwn
                  (
                    ~owner: Finance
                    ~function: $this.n > 0
                  )
                ]
                {
                  n: Integer[1];
                }
                """));
    }
